namespace Cogitatio.Interfaces;

/// <summary>
/// Where image files are kept (Azure Blob or a local folder). Paths are generated by the
/// application, never taken from user input.
/// </summary>
public interface IImageStore
{
    /// <summary>False when no image store is configured; uploads are then disabled.</summary>
    bool IsConfigured { get; }

    Task SaveAsync(string storagePath, Stream data, string contentType);

    /// <summary>Returns null when the file doesn't exist.</summary>
    Task<Stream?> OpenReadAsync(string storagePath);

    Task DeleteAsync(string storagePath);
}
